import goodsDetail from "@/pages/kefu/pc/components/goods_detail";
import stockEdit from "../components/stockEdit.vue";
import expandRow from "./tableExpand.vue";
import productDetails from '../components/productDetails.vue';
import storeLabelList from "@/components/storeLabelList";
import userLabel from "@/components/labelList";
import couponList from "@/components/couponList";
import attribute from "./attribute";
import toExcel from "../../../utils/Excel.js";
import {mapState} from "vuex";
import taoBao from "./taoBao";
import dayjs from "dayjs";
import Setting from "@/setting";
import util from "@/libs/util";
import {
  getGoodHeade,
  getGoods,
  PostgoodsIsShow,
  treeListApi,
  productShowApi,
  productUnshowApi,
  storeProductApi,
  cascaderListApi,
  productCache,
  cacheDelete,
  setDeliveryType,
  productReviewApi,
  forcedRemovalApi,
  batchProcess,
  productGetTemplateApi,
  brandList,
  allSystemForm,
  productGetVerifyApi
} from '@/api/product';
import {systemFormInfo} from '@/api/setting';
import {getSupplierList} from "@/api/supplier";
import {erpConfig, erpProduct} from "@/api/erp";
import exportExcel from "@/utils/newToExcel.js";

export default {
  name: "product_productList",
  components: {
    expandRow,
    attribute,
    taoBao,
    goodsDetail,
    stockEdit,
    productDetails,
    storeLabelList,
    userLabel,
    couponList
  },
  filters: {
    timeFormat: (value) => dayjs(value * 1000).format("YYYY-MM-DD HH:mm"),
  },
  computed: {
    ...mapState("admin/layout", ["isMobile"]),
    ...mapState("admin/userLevel", ["categoryId"]),
    labelWidth() {
      return this.isMobile ? undefined : 75;
    },
    labelPosition() {
      return this.isMobile ? "top" : "right";
    },
    brandDataList() {
      const valueToString = (item) => {
        item.value = item.value.toString();
        if (item.children) {
          item.children.map(valueToString);
        }
        return item;
      };
      return this.brandData.map(valueToString);;
    }
  },
  data() {
    return {
      formTypeList: [],
      formColumns: [
        {
          title: '表单标题',
          key: 'title',
          minWidth: 100
        },
        {
          title: '表单类型',
          key: 'name',
          minWidth: 100
        },
        {
          title: '是否必填',
          slot: 'require',
          minWidth: 100
        }
      ],
      supplierList: [],
      header: {}, //请求头部信息
      erpUrl: Setting.apiBaseURL + "/file/upload/1",
      template: false,
      modals: false,
      modalsType: false,
      delivery_type: [],
      grid: {
        xl: 7,
        lg: 8,
        md: 12,
        sm: 24,
        xs: 24,
      },
      // 订单列表
      orderData: {
        page: 1,
        limit: 10,
        type: 6,
        status: "",
        time: "",
        real_name: "",
        store_id: "",
      },
      artFrom: {
        page: 1,
        limit: 15,
        cate_id: "",
        type: "1",
        store_name: "",
        excel: 0,
        supplier_id: "",
        store_id: "",
        brand_id: [],
        store_label_id: []
      },
      list: [],
      tableList: [],
      headeNum: [],
      treeSelect: [],
      isProductBox: false,
      loading: false,
      data: [],
      total: 0,
      props: {emitPath: false, multiple: true, checkStrictly: true},
      attrTemplate: false,
      ids: [],
      display: "none",
      formSelection: [],
      selectionCopy: [],
      checkBox: false,
      isAll: 0,
      data1: [],
      value1: [],
      alertShow: false,
      goodsId: "",
      columns3: [],
      openErp: false,
      // activeKey:1
      productId: 0,
      detailsVisible: false,
      batchModal: false,
      menuActive: 1,
      storeLabelShow: false,
      storeDataLabel: [],
      labelShow: false,
      dataLabel: [],
      coupon_ids: [],
      updateIds: [],
      updateName: [],
      couponName: [],
      //自定义留言下拉选择
      customList: [
        {
          value: "text",
          label: "文本框",
        },
        {
          value: "number",
          label: "数字",
        },
        {
          value: "email",
          label: "邮件",
        },
        {
          value: "data",
          label: "日期",
        },
        {
          value: "time",
          label: "时间",
        },
        {
          value: "id",
          label: "身份证",
        },
        {
          value: "phone",
          label: "手机号",
        },
        {
          value: "img",
          label: "图片",
        },
      ],
      customBtn: false,
      batchData: {
        system_form_id: 0,//自定义表单id
        cate_id: [],
        store_label_id: [],
        delivery_type: [],
        freight: 1,
        postage: 0,
        temp_id: 0,
        give_integral: 0,
        coupon_ids: [],
        label_id: [],
        recommend: [],
        custom_form: [],
        brand_id: []
      },
      templateList: [],
      brandData: [],
      goodsDataLabel: [],
      isLabel: 0,
      checkUidList: [],
      isCheckBox: false,
      formList: [],
      auditForm:{
        is_verify:1,
        refusal:'',
        id:'',
        is_show:0,
        auto_on_time:''
      },
      auditModal:false,
    };
  },
  watch: {
    $route() {
      if (this.$route.fullPath === "/admin/product/product_list?type=5") {
        this.getPath();
      }
    },
    formSelection(value) {
      // this.checkBox = value.length === this.tableList.length;
    },
    tableList: {
      deep: true,
      handler(value) {
        value.forEach((item) => {
          this.formSelection.forEach((itm) => {
            if (itm.id === item.id) {
              item.checkBox = true;
            }
          });
        });
        const arr = this.tableList.filter((item) => item.checkBox);
        if (this.tableList.length) {
          this.checkBox = this.tableList.length === arr.length;
        } else {
          this.checkBox = false;
        }
        this.goodHeade();
      },
    },
    storeDataLabel(value) {
      this.batchData.store_label_id = value.map(item => item.id);
      this.artFrom.store_label_id = value.map(item => item.id);
    },
    couponName(value) {
      this.batchData.coupon_ids = value.map(item => item.id);
    },
    dataLabel(value) {
      this.batchData.label_id = value.map(item => item.id);
    },
    'batchData.system_form_id'(value) {
      this.customBtn = !!value;
    },
    'batchData.freight'(value) {
      switch (value) {
        case 1:
          this.batchData.postage = 0;
          this.batchData.temp_id = 0;
          break;
        case 2:
          this.batchData.temp_id = 0;
          break;
        case 3:
          this.batchData.postage = 0;
          break;
      }
    }
  },
  created() {
    this.getToken();
    productCache()
        .then((res) => {
          const info = res.data.info;
          if (!Array.isArray(info)) {
            this.alertShow = true;
          }
        })
        .catch((err) => {
          this.$Message.error(err.msg);
        });
    this.getErpConfig();
    this.getBrandList();
    this.allFormList();
  },
  mounted() {
    // this.$log.push('foo text')
    this.goodsCategory();
    this.getSupplierList();
    if (this.$route.fullPath === "/admin/product/product_list?type=5") {
      this.getPath();
    } else {
      this.getDataList();
    }
    // this.getDataList();
    this.productGetTemplate();
    this.goodHeade();
  },
  activated() {
    this.getDataList();
    this.goodHeade();
  },
  beforeRouteEnter(to, from, next) {
    next((vm) => {
      if (from.path.indexOf("/admin/product/add_product") != -1) {
        document.documentElement.scrollTop = to.meta.scollTopPosition;
      } else {
        if (vm.artFrom.page != 1 || vm.artFrom.cate_id != "" || vm.artFrom.type != "1" || vm.artFrom.store_name != ""
            || vm.artFrom.supplier_id != "" || vm.artFrom.brand_id.length != 0 || vm.goodsDataLabel.length != 0) {
          vm.artFrom = {
            page: 1,
            limit: 15,
            cate_id: "",
            type: "1",
            store_name: "",
            excel: 0,
            supplier_id: "",
            store_id: "",
            brand_id: [],
            store_label_id: []
          }
          vm.goodsDataLabel = []
          let that = vm;
          setTimeout(function () {
            that.userSearchs();
          }, 500)
        } else {
          vm.userSearchs();
        }
      }
    });
  },
  beforeRouteLeave(to, from, next) {
    if (from.meta.keepAlive) {
      from.meta.scollTopPosition = document.documentElement.scrollTop;
    }
    next();
  },
  methods: {
    allReset() {
      this.isAll = 0;
      this.isCheckBox = false;
      this.$refs.xTable.setAllCheckboxRow(false);
      this.checkUidList = [];
    },
    changeForm(e) {
      this.getSystemFormInfo(e, {type: 1});
    },
    getSystemFormInfo(e, data) {
      systemFormInfo(e, data).then(res => {
        this.formTypeList = res.data.info;
      }).catch(err => {
        this.$Message.error(err.msg);
      })
    },
    allFormList() {
      allSystemForm().then(res => {
        this.formList = res.data;
      }).catch(err => {
        this.$Message.error(err.msg);
      })
    },
    checkboxItem(e) {
      let id = parseInt(e.rowid);
      let index = this.checkUidList.indexOf(id);
      if (index !== -1) {
        this.checkUidList = this.checkUidList.filter((item) => item !== id);
      } else {
        this.checkUidList.push(id);
      }
    },
    checkboxAll() {
      // 获取选中当前值
      let obj2 = this.$refs.xTable.getCheckboxRecords(true);
      // 获取之前选中值
      let obj = this.$refs.xTable.getCheckboxReserveRecords(true);
      if (this.isAll == 0 && this.checkUidList.length <= obj.length && !this.isCheckBox) {
        obj = [];
      }
      obj = obj.concat(obj2);
      let ids = [];
      obj.forEach((item) => {
        ids.push(parseInt(item.id))
      })
      this.checkUidList = ids;
      if (!obj2.length) {
        this.isCheckBox = false;
      }
    },
    allPages(e) {
      this.isAll = e;
      if (e == 0) {
        this.$refs.xTable.toggleAllCheckboxRow();
        // this.checkboxAll();
      } else {
        if (!this.isCheckBox) {
          this.$refs.xTable.setAllCheckboxRow(true);
          this.isCheckBox = true;
          this.isAll = 1;
        } else {
          this.$refs.xTable.setAllCheckboxRow(false);
          this.isCheckBox = false;
          this.isAll = 0;
        }
        this.checkUidList = []
      }
    },
    closeStoreLabel(label) {
      let index = this.goodsDataLabel.indexOf(this.goodsDataLabel.filter(d => d.id == label.id)[0]);
      this.goodsDataLabel.splice(index, 1);
      // 商品标签id
      let storeActiveIds = [];
      this.goodsDataLabel.forEach((item) => {
        storeActiveIds.push(item.id)
      });
      this.artFrom.store_label_id = storeActiveIds;
      this.userSearchs();
    },
    // 品牌列表
    getBrandList() {
      brandList().then(res => {
        this.brandData = res.data
      }).catch(err => {
        this.$Message.error(err.msg);
      })
    },
    //获取供应商列表；
    getSupplierList() {
      getSupplierList()
          .then(async (res) => {
            this.supplierList = res.data;
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
    },
    saveAuditConfirm(){
      productGetVerifyApi(this.auditForm.id).then(res=>{
        if(res.data.verify == 1){
          this.$Modal.confirm({
            title: '提示',
            content: '商品售价小于结算价，是否通过审核',
            onOk: () => {
              productReviewApi(this.auditForm.id,this.auditForm).then(res=>{
                this.auditForm.id = '';
                this.auditForm.refusal = '';
                this.auditModal = false;
                this.getDataList();
                this.goodHeade();
              }).catch(err=>{
                this.$Message.error(res.msg);
              })
            }
          });
        }else{
          productReviewApi(this.auditForm.id,this.auditForm).then(res=>{
            this.auditForm.id = '';
            this.auditForm.refusal = '';
            this.auditModal = false;
            this.getDataList();
            this.goodHeade();
          }).catch(err=>{
            this.$Message.error(res.msg);
          })
        }
      })
    },
    goodsOn(e){
      if(e==0 || e==1){
        this.auditForm.auto_on_time = '';
      }
    },
    // 审核
    auditGoods(row) {
      this.auditForm.id = row.id;
      this.auditModal = true;

    },
    // 强制下架
    forcedRemoval(row) {
      this.$modalForm(forcedRemovalApi(row.id)).then(() => this.getDataList())
    },
    frontDownload() {
      let a = document.createElement("a"); //创建一个<a></a>标签
      a.href = "/statics/ERP商品导入模板.xlsx"; // 给a标签的href属性值加上地址，注意，这里是绝对路径，不用加 点.
      a.download = "ERP商品导入模板.xlsx"; //设置下载文件文件名，这里加上.xlsx指定文件类型，pdf文件就指定.fpd即可
      a.style.display = "none"; // 障眼法藏起来a标签
      document.body.appendChild(a); // 将a标签追加到文档对象中
      a.click(); // 模拟点击了a标签，会触发a标签的href的读取，浏览器就会自动下载了
      a.remove(); // 一次性的，用完就删除a标签
    },
    handleFormatError(file) {
      return this.$Message.error("必须上传xlsx格式文件");
    },
    // 上传头部token
    getToken() {
      this.header["Authori-zation"] = "Bearer " + util.cookies.get("token");
    },
    upFile(res) {
      erpProduct({path: res.data.src})
          .then((res) => {
            this.$Message.success(res.msg);
            this.getDataList();
          })
          .catch((err) => {
            return this.$Message.error(err.msg);
          });
    },
    beforeUpload() {
      let promise = new Promise((resolve) => {
        this.$nextTick(function () {
          resolve(true);
        });
      });
      return promise;
    },
    //erp配置
    getErpConfig() {
      erpConfig()
          .then((res) => {
            this.openErp = res.data.open_erp;
          })
          .catch((err) => {
            this.$Message.error(err.msg);
          });
    },
    stockChange(stock) {
      this.tableList.forEach((item) => {
        if (this.goodsId == item.id) {
          item.stock = stock;
        }
      });
    },
    // 库存管理
    stockControl(row) {
      this.goodsId = row.id;
      this.$refs.stock.modals = true;
      this.$refs.stock.productAttrs(row);
    },
    cancelDelivery() {
      this.modalsType = false;
      this.delivery_type = [];
    },
    deliveryType() {
      this.modalsType = true;
    },
    putDelivery() {
      if (this.delivery_type.length === 0) {
        this.$Message.error("请选择要配送的商品");
      } else {
        let data = {
          all: this.isAll,
          delivery_type: this.delivery_type,
          ids: this.checkUidList
        };
        // if (this.isAll == 0) {
        //   data.ids = this.checkUidList;
        // }
        setDeliveryType(data)
            .then((res) => {
              this.$Message.success(res.msg);
              this.modalsType = false;
              this.delivery_type = [];
              this.isAll = 0;
              this.getDataList();
            })
            .catch((res) => {
              this.$Message.error(res.msg);
            });
      }
    },
    // 商品详情
    lookGoods(id) {
      this.goodsId = id;
      this.isProductBox = true;
    },
    closeAlert() {
      cacheDelete()
          .then((res) => {
            this.$Message.success(res.msg);
          })
          .catch((err) => {
            this.$Message.error(err.msg);
          });
    },
    getPath() {
      this.columns2 = [...this.columns];
      if (name !== "1" && name !== "2") {
        this.columns2.shift();
      }
      this.artFrom.page = 1;
      this.artFrom.type = this.$route.query.type.toString();
      this.getDataList();
    },
    changeMenu(row, name, index) {
      switch (name) {
        case "1":
          this.$router.push({path: "/admin/product/product_reply/" + row.id});
          break;
        case "2":
          this.del(row, "恢复商品", index, name);
          break;
        case "3":
          this.del(row, "移入回收站", index, name);
          break;
        case "4":
          this.stockControl(row);
          break;
        case "5":
          this.$modalForm(forcedRemovalApi(row.id)).then(() => {
            this.getDataList();
            this.goodHeade();
          })
          break;
        case "6":
          this.$router.push({path: "/admin/product/add_product/", query: {copy: row.id}});
          break;
        case "7":
          this.delProduct(row,index);
          break;
      }
    },
    delProduct(row,num){
      let delfromData = {
        title: '删除商品',
        num: num,
        url: `product/product/thorough/${row.id}`,
        method: "DELETE",
        ids: "",
        tips: `确定要删除该商品吗？`,
      };
      this.$modalSure(delfromData)
          .then((res) => {
            this.$Message.success(res.msg);
            this.tableList.splice(num, 1);
            this.goodHeade();
            this.allReset();
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
    },
    // 数据导出；
    async exports() {
      let [th, filekey, data, fileName] = [[], [], [], ""];
      let formValidate = this.artFrom;
      let excelData = {};
      excelData.ids = this.checkUidList.join();
      if (this.isAll == 1) {
        excelData.all = 1;
        excelData.cate_id = formValidate.cate_id;
        excelData.type = formValidate.type;
        excelData.store_name = formValidate.store_name;
        excelData.supplier_id = formValidate.supplier_id;
        excelData.brand_id = formValidate.brand_id;
        excelData.store_label_id = formValidate.store_label_id;
        excelData.excel = formValidate.excel;
      }
      excelData.page = 1;
      for (let i = 0; i < excelData.page + 1; i++) {
        let lebData = await this.getExcelData(excelData);
        if (!fileName) fileName = lebData.filename;
        if (!filekey.length) {
          filekey = lebData.filekey;
        }
        if (!th.length) th = lebData.header;
        if (lebData.export.length) {
          data = data.concat(lebData.export);
          excelData.page++;
        } else {
          exportExcel(th, filekey, fileName, data);
          return;
        }
      }
    },
    getExcelData(excelData) {
      return new Promise((resolve, reject) => {
        storeProductApi(excelData).then((res) => {
          return resolve(res.data);
        });
      });
    },
    changeTemplate(e) {
      // this.template = e;
    },
    freight() {
      this.$refs.template.isTemplate = true;
    },
    // 批量上架
    onShelves() {
      if (this.isAll != 1 && this.checkUidList.length === 0) {
        this.$Message.warning("请选择要上架的商品");
      } else {
        let data = {
          all: this.isAll,
          ids: this.checkUidList
        };
        if (this.isAll == 1) {
          data.where = {
            cate_id: this.artFrom.cate_id,
            excel: this.artFrom.excel,
            store_name: this.artFrom.store_name,
            type: this.artFrom.type,
          };
        }
        productShowApi(data)
            .then((res) => {
              this.$Message.success(res.msg);
              this.goodHeade();
              this.getDataList();
              this.allReset();
            })
            .catch((res) => {
              this.$Message.error(res.msg);
            });
      }
    },
    // 批量下架
    onDismount() {
      if (this.isAll != 1 && this.checkUidList.length === 0) {
        this.$Message.warning("请选择要下架的商品");
      } else {
        let data = {
          all: this.isAll,
          ids: this.checkUidList
        };
        if (this.isAll == 1) {
          data.where = {
            cate_id: this.artFrom.cate_id,
            excel: this.artFrom.excel,
            store_name: this.artFrom.store_name,
            type: this.artFrom.type,
          };
        }
        productUnshowApi(data)
            .then((res) => {
              this.$Message.success(res.msg);
              this.goodHeade();
              this.getDataList();
              this.allReset();
            })
            .catch((res) => {
              this.$Message.error(res.msg);
            });
      }
    },
    // 添加淘宝商品成功
    onClose() {
      this.modals = false;
    },
    // 复制淘宝
    onCopy() {
      this.$router.push({
        path: "/admin/product/add_product",
        query: {type: -1},
      });
      // this.modals = true;
    },
    // tab选择
    onClickTab(name) {
      this.allReset();
      this.artFrom.type = name;
      // this.columns2 = [...this.columns];
      // if (name !== "1" && name !== "2") {
      //   this.columns2.shift();
      // }
      // let obj = [...this.columns];
      // obj.shift();
      // obj.splice(8, 1);
      // this.columns3 = obj;
      // this.checkBox = false;
      this.artFrom.page = 1;
      this.getDataList();
      this.goodHeade();
    },
    // 下拉树
    handleCheckChange(data) {
      let value = "";
      let title = "";
      this.list = [];
      this.artFrom.cate_id = 0;
      data.forEach((item, index) => {
        value += `${item.id},`;
        title += `${item.title},`;
      });
      value = value.substring(0, value.length - 1);
      title = title.substring(0, title.length - 1);
      this.list.push({
        value,
        title,
      });
      this.artFrom.cate_id = value;
      this.getDataList();
    },
    // 获取商品表单头数量
    goodHeade() {
      // let data = {
      //   store_name: this.artFrom.store_name,
      //   cate_id: this.artFrom.cate_id || "",
      //   supplier_id: this.artFrom.supplier_id || "",
      //   store_id: this.artFrom.store_id || "",
      //   brand_id: this.artFrom.brand_id || [],
      //   store_label_id: this.artFrom.store_label_id || []
      // };
      getGoodHeade(this.artFrom)
          .then((res) => {
            this.headeNum = res.data.list;
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
    },
    // 商品分类；
    goodsCategory() {
      cascaderListApi(1).then((res) => {
        this.data1 = res.data;
      }).catch((res) => {
        this.$Message.error(res.msg);
      });
    },
    // 商品列表；
    getDataList() {
      this.loading = true;
      this.artFrom.cate_id = this.artFrom.cate_id || "";
      getGoods(this.artFrom)
          .then((res) => {
            let data = res.data;
            this.tableList = data.list;
            this.total = data.count;
            this.loading = false;
            this.$nextTick(function () {
              if (this.isAll == 1) {
                if (this.isCheckBox) {
                  this.$refs.xTable.setAllCheckboxRow(true);
                } else {
                  this.$refs.xTable.setAllCheckboxRow(false);
                }
              } else {
                let obj = this.$refs.xTable.getCheckboxReserveRecords(true);
                if (!this.checkUidList.length || this.checkUidList.length <= obj.length) {
                  this.$refs.xTable.setAllCheckboxRow(false);
                }
              }
            })
          })
          .catch((res) => {
            this.loading = false;
            this.$Message.error(res.msg);
          });
    },
    pageChange(currentPage) {
      this.artFrom.page = currentPage.currentPage;
      this.getDataList();
      // this.$refs.table.clearCurrentRow();
    },
    // cascaderSearchs(value, selectedData) {
    //   this.artFrom.cate_id = value[value.length - 1];
    //   this.userSearchs();
    // },
    // 表格搜索
    userSearchs(e) {
      this.allReset();
      this.artFrom.page = 1;
      this.formSelection = [];
      this.goodHeade();
      this.getDataList();
    },
    // 上下架
    changeSwitch(row) {
      PostgoodsIsShow(row.id, row.is_show)
          .then((res) => {
            this.$Message.success(res.msg);
            this.goodHeade();
            this.getDataList();
            this.allReset();
          })
          .catch((res) => {
            this.$Message.error(res.msg);
            this.goodHeade();
            this.getDataList();
          });
    },
    // 数据导出；
    exportData: function () {
      let th = [
        "商品名称",
        "商品简介",
        "商品分类",
        "价格",
        "库存",
        "销量",
        "收藏人数",
      ];
      let filterVal = [
        "store_name",
        "store_info",
        "cate_name",
        "price",
        "stock",
        "sales",
        "collect",
      ];
      this.where.page = "nopage";
      getGoods(this.where).then((res) => {
        let data = res.data.map((v) => filterVal.map((k) => v[k]));
        let fileTime = Date.parse(new Date());
        let [fileName, fileType, sheetName] = [
          "商户数据_" + fileTime,
          "xlsx",
          "商户数据",
        ];
        toExcel({th, data, fileName, fileType, sheetName});
      });
    },
    // 属性弹出；
    attrTap() {
      this.attrTemplate = true;
    },
    changeTemplate(msg) {
      this.attrTemplate = msg;
    },
    // 编辑
    edit(row) {
      this.$router.push({path: "/admin/product/add_product/" + row.id});
    },
    // 确认
    del(row, tit, num, name) {
      let delfromData = {
        title: tit,
        num: num,
        url: `product/product/${row.id}`,
        method: "DELETE",
        ids: "",
        tips: `确定要移${name == 2 ? '出' : '入'}回收站吗？`,
      };
      this.$modalSure(delfromData)
          .then((res) => {
            this.$Message.success(res.msg);
            this.tableList.splice(num, 1);
            this.goodHeade();
            this.allReset();
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
    },
    // 删除成功
    // submitModel () {
    //     this.tableList.splice(this.delfromData.num, 1);
    //     this.goodHeade();
    // }
    // 商品详情
    details(id) {
      this.productId = id;
      this.detailsVisible = true;
    },
    openBatch() {
      this.isLabel = 0;
      this.batchModal = true;
    },
    menuSelect(name) {
      this.menuActive = name;
    },
    activeStoreData(storeDataLabel) {
      this.storeLabelShow = false;
      if (this.isLabel) {
        this.goodsDataLabel = storeDataLabel;
        // 商品标签id
        let storeActiveIds = [];
        storeDataLabel.forEach((item) => {
          storeActiveIds.push(item.id)
        });
        this.artFrom.store_label_id = storeActiveIds;
        this.userSearchs();
      } else {
        this.storeDataLabel = storeDataLabel;
      }
    },
    // 标签弹窗关闭
    storeLabelClose() {
      this.storeLabelShow = false;
    },
    openStoreLabel(row) {
      this.storeLabelShow = true;
      this.$refs.storeLabel.storeLabel(JSON.parse(JSON.stringify(this.storeDataLabel)));
    },
    openGoodsLabel(row) {
      this.storeLabelShow = true;
      this.$refs.storeLabel.storeLabel(JSON.parse(JSON.stringify(this.goodsDataLabel)));
      this.isLabel = 1;
    },
    tagClose(id) {
      if (this.menuActive == 2) {
        let index = this.storeDataLabel.findIndex(item => item.id === id);
        this.storeDataLabel.splice(index, 1);
      } else {
        let index = this.dataLabel.findIndex(item => item.id === id);
        this.dataLabel.splice(index, 1);
      }
    },
    activeData(dataLabel) {
      this.labelShow = false;
      this.dataLabel = dataLabel;
    },
    // 标签弹窗关闭
    labelClose() {
      this.labelShow = false;
    },
    openLabel() {
      this.labelShow = true;
      this.$refs.userLabel.userLabel(JSON.parse(JSON.stringify(this.dataLabel)));
    },
    // 添加优惠券
    addCoupon() {
      this.$refs.couponTemplates.isTemplate = true;
      this.$refs.couponTemplates.tableList();
    },
    nameId(id, names) {
      this.coupon_ids = id;
      this.couponName = this.unique(names);
    },
    handleClose(name) {
      let index = this.couponName.indexOf(name);
      this.couponName.splice(index, 1);
      let couponIds = this.coupon_ids;
      couponIds.splice(index, 1);
      this.updateIds = couponIds;
      this.updateName = this.couponName;
    },
    //对象数组去重；
    unique(arr) {
      const res = new Map();
      return arr.filter((arr) => !res.has(arr.id) && res.set(arr.id, 1));
    },
    // 添加表单
    addForm() {
      this.batchData.custom_form.push({
        key: Date.now(),
        title: '',
        label: '',
        status: 0
      });
    },
    // 删除表单
    delForm(item) {
      let index = this.batchData.custom_form.findIndex(val => val === item);
      if (index !== -1) {
        this.batchData.custom_form.splice(index, 1);
      }
    },
    cancelBatch() {
      this.batchModal = false;
      this.auditModal = false;
    },
    saveBatch() {
      if (this.customBtn && this.batchData.system_form_id == 0) {
        return this.$Message.warning('请选择自定义表单模板');
      }

      this.artFrom.store_label_id = [];
      let data = {
        type: this.menuActive,
        ids: this.checkUidList,
        all: this.isAll,
        where: this.artFrom,
        data: this.batchData,
      };
      batchProcess(data).then(res => {
        this.$Message.success(res.msg);
        this.batchModal = false;
      }).catch(res => {
        this.$Message.error(res.msg);
      });
    },
    // 获取运费模板；
    productGetTemplate() {
      productGetTemplateApi().then((res) => {
        this.templateList = res.data;
      });
    },
    customMessBtn(e) {
      if (!e) {
        this.batchData.system_form_id = 0;
      }
    },
    batchVisibleChange() {
      this.batchData = {
        cate_id: [],
        store_label_id: [],
        delivery_type: [],
        freight: 1,
        postage: 0,
        temp_id: 0,
        give_integral: 0,
        coupon_ids: [],
        label_id: [],
        recommend: [],
        custom_form: [],
        system_form_id: 0
      };
      this.storeDataLabel = [];
      this.couponName = [];
      this.dataLabel = [];
      this.menuActive = 1;
    }
  },
};
